3.4 背景範囲と背景点

# 出現記録の周囲 dist メートルのバッファー(背景範囲)を作る。
make_bg_buffer &lt;- function(occs, envs, dist = 500000) {
  eckertIV &lt;- "+proj=eck4 +lon_0=0 +x_0=0 +y_0=0 +datum=WGS84 +units=m +no_defs"
  occs |&gt;
    sf::st_as_sf(coords = c("longitude", "latitude"), crs = terra::crs(envs)) |&gt;
    sf::st_transform(crs = eckertIV) |&gt;
    sf::st_buffer(dist = dist) |&gt;
    sf::st_union() |&gt;
    sf::st_sf() |&gt;
    sf::st_transform(crs = terra::crs(envs))
}

# 環境ラスターを、背景範囲の形に切り抜く。
mask_envs &lt;- function(envs, bg_buffer) {
  envs |&gt;
    terra::crop(bg_buffer) |&gt;
    terra::mask(bg_buffer)
}

# 背景範囲から n 個の背景点を無作為に取る。
sample_bg &lt;- function(envs_bg, occs, n = 10000) {
  bg &lt;- terra::spatSample(envs_bg, size = n, na.rm = TRUE,
                          values = FALSE, xy = TRUE) |&gt;
    as.data.frame()
  colnames(bg) &lt;- colnames(occs)
  bg
}

3.5 モデルの作成と選択

# maxnet のモデルを、特徴クラス(fc)と正則化の倍率(rm)のすべての組み合わせで作って評価する。
# 設定を、ここでなく引数にしておくと、_targets.R で設定を変えやすい。
run_enmeval &lt;- function(occs, envs, bg, fc, rm) {
  ENMeval::ENMevaluate(occs = occs, envs = envs, bg = bg,
                       algorithm = "maxnet", partitions = "block",
                       tune.args = list(fc = fc, rm = rm), quiet = TRUE)
}

# 逐次的な基準で最適モデルを選ぶ(欠損率が最小 → 同点なら検証 CBI が最大)。
select_best &lt;- function(res) {
  res |&gt;
    dplyr::filter(!is.na(or.10p.avg)) |&gt;
    dplyr::filter(or.10p.avg == min(or.10p.avg)) |&gt;
    dplyr::filter(cbi.val.avg == max(cbi.val.avg))
}

# 最適モデルの設定で、ヌルモデルを作る。
run_nulls &lt;- function(e, best, no_iter = 10) {
  ENMeval::ENMnulls(e, mod.settings = list(fc = as.character(best$fc), rm = best$rm),
                    no.iter = no_iter, quiet = TRUE)
}







ノート補足:図を描くコードは関数に入れない



応答曲線や予測地図などの 図 は、パイプラインには入れません。 パイプラインは「結果(データ)」を作るもので、図は、保存された結果を読み込んで、必要なときに描きます (結果を読み込むで行います)。
